  </span>;
}

export function ArtifactChat({ conversationId, initial, requests: initialRequests, model, messagesCursor, running: initialRunning, artifactId, artifact, home }: { conversationId: string; initial: ChatItem[]; requests: ChatNode[]; model: string | null; messagesCursor: string | null; running: string | null; artifactId?: string; artifact: string; home: HomeVersions }) {
  const router = useRouter();
  const [messages, setMessages] = useState(initial);
  const [requests, setRequests] = useState(initialRequests);
  const branch = useChatPath(requests);
  const access = useAiAccess();
  const [older, setOlder] = useState(messagesCursor);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const [historyError, setHistoryError] = useState("");
  const prepended = useRef(false);
  const [running, setRunning] = useState(initialRunning);
  const [pending, setPending] = useState<PendingExchange | null>(null);
  const live = useRef<PendingExchange | null>(null);
  const scroll = useRef<HTMLDivElement>(null);
  useEffect(() => { if (prepended.current) { prepended.current = false; return; } if (scroll.current) scroll.current.scrollTop = scroll.current.scrollHeight; }, [messages.length, pending]);
  const [request, setRequest] = useState<string>();
  const [claimFailed, setClaimFailed] = useState(false);
  const [claimAttempt, setClaimAttempt] = useState(0);
  useEffect(() => {
    const listener = (event: Event) => setRequest((event as CustomEvent<string>).detail);
    window.addEventListener(SEND_EVENT, listener);
    return () => window.removeEventListener(SEND_EVENT, listener);
  }, []);
  useEffect(() => {
    if (!artifactId) return;
    claimFirstPrompt(artifactId).then(prompt => { setClaimFailed(false); if (prompt) setRequest(prompt); else router.refresh(); }, () => setClaimFailed(true));
  }, [artifactId, claimAttempt, router]);

  const resuming = running && !pending;
  const [unreachable, setUnreachable] = useState(false);
  usePolling(signal => fetch(`/api/conversations/${conversationId}`, { cache: "no-store", signal }).then(response => { if (!response.ok) throw new Error(); return response.json() as Promise<Loaded>; }).then(data => {
    setUnreachable(false);
    if (data.running) return;
    setMessages(current => [...current.filter(message => !data.messages.some(item => item.id === message.id)), ...data.messages]); if (data.requests) setRequests(data.requests); setRunning(null); router.refresh();
  }).catch(() => { if (!signal.aborted) setUnreachable(true); }), 3000, !!resuming);

  async function loadOlder() {
    if (!older || loadingOlder) return;
    setLoadingOlder(true); setHistoryError("");
    try {
      const response = await fetch(`/api/conversations/${conversationId}?${new URLSearchParams({ messagesBefore: older })}`, { cache: "no-store" });
      if (!response.ok) throw new Error("Could not load older messages. Try again.");
      const data = await response.json() as Loaded;
      prepended.current = true;
      setMessages(current => [...data.messages.filter(message => !current.some(item => item.id === message.id)), ...current]);
      setOlder(data.messagesCursor);
    } catch (cause) { setHistoryError(cause instanceof Error ? cause.message : "Could not load older messages. Try again."); }
    finally { setLoadingOlder(false); }
  }

  function onStart(_id: string, question: string, attachments: ChatAttachment[], spoken: boolean, after?: string | null) { live.current = { question, attachments, tools: [], spoken, after }; setPending(live.current); }
  function onEvent(_id: string, event: ChatStreamEvent) {
    if (!live.current) return;
    const before = live.current;
    live.current = applyChatEvent(before, event);
    setPending(live.current);
    if (event.type === "tool" && event.state === "done" && ["write_page", "card_preset", "write_card", "remove_card"].includes(event.name ?? "")) router.refresh();
  }
  function onDone(_id: string, question: string, result: (ChatAnswer & { requestId: string }) | null, attachments: ChatAttachment[]) {
    const finished = live.current ?? undefined;
    live.current = null; setPending(null); setRequest(undefined);
    if (!result) return;
    const exchange = localExchange(question, result, finished, attachments);
    setMessages(current => [...current, ...exchange.messages]);
    setRequests(current => [...current, exchange.node]);
    router.refresh();
  }

  return <div className="flex min-h-0 flex-1 flex-col">
    <div ref={scroll} aria-label="Artifact chat messages" className="relative min-h-0 flex-1 overflow-y-auto pr-1">
      {older && <button type="button" disabled={loadingOlder} onClick={() => void loadOlder()} className="mb-4 min-h-9 rounded-lg border border-border px-3 text-xs text-muted-foreground disabled:opacity-50">{loadingOlder ? "Loading older messages…" : "Older messages"}</button>}
      {historyError && <p role="alert" className="mb-3 text-sm text-danger">{historyError}</p>}
      {messages.length || pending || resuming ? <ChatMessages compact messages={messages} path={branch.path} onPick={branch.pick} editable models={access?.models} pending={pending ?? (resuming ? RESUMED_RUN : undefined)} toolResult={(step, key) => <SavedVersion key={key} step={step} artifactId={artifact} home={home} />} />
        : <p className="text-sm text-muted-foreground">Describe what to build. Ask for a Home card any time, e.g. “add this to Home as a small card”.</p>}
    </div>
    {unreachable && resuming && <p role="alert" className="text-xs text-warning">Could not check on this build. It may still be running. Moneo keeps trying.</p>}
    {claimFailed && <p role="alert" className="text-sm text-danger">Could not start your request. <button type="button" onClick={() => setClaimAttempt(count => count + 1)} className="underline">Try again</button></p>}
    <ChatForm conversationId={conversationId} selectionKey={`moneo-artifact-${conversationId}`} autoSend={request} placeholder="Change the page or a card…" parent={branch.end} model={model} persisted onStart={onStart} onEvent={onEvent} onDone={onDone} />
  </div>;
}
"use client";

import { useEffect, useRef, useState } from "react";
import { Sparkles } from "lucide-react";
import { VoiceInput } from "@/components/voice-input";
import { withSpoken } from "@/components/chat-composer";
import { SafeForm } from "@/components/safe-form";
import { createArtifactSafely } from "./actions";

const EXAMPLE_EVENT = "moneo-artifact-example";

export function ArtifactExamples({ examples }: { examples: readonly { title: string; summary: string; prompt: string }[] }) {
  return <ul className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{examples.map(example => <li key={example.title}>
    <button type="button" onClick={() => window.dispatchEvent(new CustomEvent(EXAMPLE_EVENT, { detail: example.prompt }))} className="block h-full w-full rounded-xl border border-border bg-card p-4 text-left hover:bg-muted">
      <span className="block font-medium">{example.title}</span>
      <span className="mt-1 block text-xs text-muted-foreground">{example.summary}</span>
    </button></li>)}</ul>;
}

export function ArtifactPrompt({ defaultValue = "", placeholder }: { defaultValue?: string; placeholder: string }) {
  const input = useRef<HTMLTextAreaElement>(null);
  const [replaced, setReplaced] = useState("");
  const lastExample = useRef("");
  useEffect(() => {
    const use = (event: Event) => {
      const field = input.current;
      if (!field) return;
      if (field.value.trim() && field.value !== lastExample.current) setReplaced(field.value);
      field.value = lastExample.current = (event as CustomEvent<string>).detail;
      field.focus();
    };
    window.addEventListener(EXAMPLE_EVENT, use);
    return () => window.removeEventListener(EXAMPLE_EVENT, use);
  }, []);
  function speak(text: string, submit: boolean) {
    const field = input.current;
    if (!field) return;
    field.value = withSpoken(field.value, text).slice(0, 4000);
    if (submit) field.form?.requestSubmit(); else field.focus();
  }
  return <SafeForm action={createArtifactSafely} className="relative grid gap-2">
    <label htmlFor="artifact-prompt" className="text-sm font-medium">Describe your report or tool</label>
    <textarea ref={input} id="artifact-prompt" name="prompt" required maxLength={4000} rows={4} defaultValue={defaultValue} placeholder={placeholder} aria-describedby="artifact-prompt-help"
      onKeyDown={event => { if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) event.currentTarget.form?.requestSubmit(); }}
      className="w-full resize-y rounded-lg border border-border bg-card px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring" />
    {replaced && <button type="button" onClick={() => { if (input.current) { input.current.value = replaced; input.current.focus(); } setReplaced(""); }} className="justify-self-start text-xs underline">Restore my text</button>}
    <div className="flex flex-wrap items-center justify-between gap-2">
      <span id="artifact-prompt-help" className="text-xs text-muted-foreground">Build uses an AI request and your real data, read-only. Ctrl or Cmd+Enter also builds. Usage is under Settings.</span>
      <span className="flex items-center gap-1.5"><VoiceInput onSend={text => speak(text, true)} onDone={text => speak(text, false)} /><button type="submit" className="inline-flex min-h-10 items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50 whitespace-nowrap"><Sparkles className="size-3.5" aria-hidden="true" />Build</button></span>
    </div>
  </SafeForm>;
}

