import { mkdirSync } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { chromium, devices } from "@playwright/test";
import postgres from "postgres";

process.loadEnvFile(".env.qa");
const QA_APP = process.env.E2E_BASE_URL ?? "http://localhost:3100";
const label = process.argv[2];
const folder = path.join(".qa", "shots", label);
mkdirSync(folder, { recursive: true });
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [{ id: ws }] = await db`select w.id from public.workspaces w join auth.users u on u.id = w.owner_id where u.email = ${process.env.E2E_USER_EMAIL}`;
const [{ has }] = await db`select exists(select 1 from information_schema.columns where table_name = 'artifact_versions' and column_name = 'request_id') as has`;

const page = (version, period, color) => `<!doctype html><html><body style="font-family:system-ui;margin:0;padding:32px;background:${color};color:#111">
<p style="margin:0;font-size:14px;opacity:.7">Page v${version}</p><h1 style="margin:8px 0 24px;font-size:32px">Spending by ${period}</h1>
<div style="display:flex;gap:12px;align-items:flex-end;height:160px">${[60, 90, 45, 120, 80, 100].map(h => `<div style="flex:1;height:${h}px;background:#111;border-radius:6px"></div>`).join("")}</div></body></html>`;

const artifact = randomUUID(), conversation = randomUUID(), r1 = randomUUID(), r2 = randomUUID(), r3 = randomUUID();
const write = version => db.json([{ name: "write_page", input: { title: "Spending", brief: "…", queries: [] }, output: JSON.stringify({ saved: true, pageVersion: version, note: "The Page tab shows it now." }) }]);
const at = minutes => new Date(Date.now() - minutes * 60_000);
async function seed() {
  await db`insert into public.artifacts (id, workspace_id, title) values (${artifact}, ${ws}, 'Spending explorer')`;
  await db`insert into public.conversations (id, workspace_id, title, artifact_id) values (${conversation}, ${ws}, 'Spending explorer', ${artifact})`;
  const requests = [
    [r1, "Build a page of my spending by month", "Built a page that shows your spending by month.", null, null, "gpt-6-luna", 1, 6],
    [r2, "Make it weekly instead", "Switched the page to weekly totals.", r1, null, "gpt-6-luna", 2, 4],
    [r3, "Make it weekly instead", "Rebuilt it with weekly totals and a calmer palette.", r1, r2, "claude-opus-5-5", 3, 2],
  ];
  for (const [id, message, answer, parent, regenerates, model, version, minutes] of requests) {
